script:
(function () {
  'use strict';
  // 12-month cash flow projection.
  //   closing[m] = opening[m] + cashIn[m] - cashOut[m]; opening[1] = starting cash; opening[m+1] = closing[m].
  //   Lowest balance = the smallest of the 12 closing balances (the month it first occurs is reported).
  //   Months below $0 = closing < 0; months below cushion = closing < cushion.
  //   Extra cash needed = max(0, cushion - lowest balance): the amount that, added at the start,
  //   keeps every closing balance at or above the cushion.
  //   Fill helper: month k amount = typical x (1 + g)^(k-1), rounded to the dollar.
  // Verified (scratchpad b4biz/cf.test.js): default example, starting cash $20,000, closing balances
  //   15,000 / 8,000 / 5,000 / -1,000 / 1,000 / 6,000 / 9,000 / 10,000 / 8,000 / 4,000 / 11,000 / 23,000
  //   (hand-summed); lowest -$1,000 in Apr, 1 month below $0, 3 months below the $5,000 cushion,
  //   extra cash needed $6,000, net +$3,000; a first month of Oct relabels the months Oct..Sep;
  //   fill helper $10,000 growing 10% gives 10,000 / 11,000 / 12,100 / ... / 28,531 in month 12 (= 10,000 x 1.1^11);
  //   blank boxes count as $0; negative cash in/out shows an error instead of a result.
  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function fmt(x) { return Math.abs(x) < 0.5 ? money.format(0) : money.format(x); }
  function signed(x) { return Math.abs(x) < 0.5 ? money.format(0) : (x > 0 ? '+' : '−') + money.format(Math.abs(x)); }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function project(start, ins, outs, cushion) {
    var bal = start, rows = [], lowest = Infinity, lowIdx = 0, neg = 0, below = 0, tin = 0, tout = 0;
    for (var i = 0; i < ins.length; i++) {
      var open = bal;
      bal = open + ins[i] - outs[i];
      tin += ins[i]; tout += outs[i];
      if (bal < lowest - 1e-9) { lowest = bal; lowIdx = i; }
      if (bal < 0) neg++;
      if (bal < cushion) below++;
      rows.push({ open: open, cin: ins[i], cout: outs[i], close: bal });
    }
    return { rows: rows, lowest: lowest, lowIdx: lowIdx, neg: neg, below: below, totalIn: tin, totalOut: tout,
             ending: bal, needed: Math.max(0, cushion - lowest) };
  }

  function monthName(first, i) { return MONTHS[(first + i) % 12]; }

  function readCell(id) {
    var el = document.getElementById(id), raw = el.value.trim();
    if (raw === '') { el.setAttribute('aria-invalid', 'false'); return 0; }
    var v = parseFloat(raw), bad = isNaN(v) || v < 0 || v > 1e10;
    el.setAttribute('aria-invalid', String(bad));
    return bad ? NaN : v;
  }

  function relabel(first) {
    for (var i = 0; i < 12; i++) {
      var name = monthName(first, i);
      set('cfMonth' + (i + 1), name);
      document.getElementById('cfIn' + (i + 1)).setAttribute('aria-label', 'Cash in, ' + name);
      document.getElementById('cfOut' + (i + 1)).setAttribute('aria-label', 'Cash out, ' + name);
    }
  }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }

  function clearResults() {
    ['cfLowest', 'cfNegMonths', 'cfEnding', 'cfNeeded', 'cfTotalIn', 'cfTotalOut', 'cfNet', 'cfBelowBuffer', 'cfAvgNet'].forEach(function (id) { set(id, '–'); });
    ['cfLowestNote', 'cfNegNote', 'cfEndingNote', 'cfNeededNote'].forEach(function (id) { set(id, ''); });
    document.getElementById('cfVerdict').hidden = true;
    clearBody('cfTable');
  }

  function update() {
    var first = parseInt(document.getElementById('cfFirst').value, 10) || 0;
    relabel(first);
    var start = parseFloat(document.getElementById('cfStart').value);
    var cushionRaw = document.getElementById('cfBuffer').value.trim();
    var cushion = cushionRaw === '' ? 0 : parseFloat(cushionRaw);
    var ins = [], outs = [], cellsOk = true;
    for (var i = 1; i <= 12; i++) {
      var a = readCell('cfIn' + i), b = readCell('cfOut' + i);
      if (isNaN(a) || isNaN(b)) cellsOk = false;
      ins.push(a); outs.push(b);
    }
    var error = document.getElementById('cfError'), problem = '';
    if (isNaN(start) || Math.abs(start) > 1e10) problem = 'Enter your starting cash (it can be negative if you begin overdrawn).';
    else if (isNaN(cushion) || cushion < 0 || cushion > 1e10) problem = 'Enter a minimum cash cushion of $0 or more.';
    else if (!cellsOk) problem = 'Monthly cash in and cash out must be $0 or more. Check the highlighted months.';
    error.hidden = !problem;
    error.textContent = problem;
    if (problem) { clearResults(); return; }

    var r = project(start, ins, outs, cushion);
    var lowName = monthName(first, r.lowIdx);
    set('cfLowest', fmt(r.lowest));
    set('cfLowestNote', 'Reached at the end of ' + lowName + '.');
    set('cfNegMonths', String(r.neg));
    set('cfNegNote', r.neg ? 'Months that end overdrawn without extra funding.' : 'Every month ends with cash in the bank.');
    set('cfEnding', fmt(r.ending));
    set('cfEndingNote', 'Change of ' + signed(r.ending - start) + ' over 12 months.');
    set('cfNeeded', fmt(r.needed));
    set('cfNeededNote', r.needed > 0 ? 'Cash or credit to have ready so no month drops below your ' + fmt(cushion) + ' cushion.' : 'Your balance never drops below your ' + fmt(cushion) + ' cushion.');
    set('cfTotalIn', fmt(r.totalIn));
    set('cfTotalOut', fmt(r.totalOut));
    set('cfNet', signed(r.totalIn - r.totalOut));
    set('cfBelowBuffer', String(r.below));
    set('cfAvgNet', signed((r.totalIn - r.totalOut) / 12));

    var verdict = document.getElementById('cfVerdict');
    verdict.hidden = false;
    if (r.neg > 0) {
      verdict.className = 'callout callout-warning mt-5';
      set('cfVerdictTitle', 'You run out of cash in ' + r.neg + (r.neg === 1 ? ' month' : ' months'));
      set('cfVerdictText', 'The balance falls to ' + fmt(r.lowest) + ' in ' + lowName + '. Line up ' + fmt(-r.lowest) + ' or more of funding (a credit line, faster customer collections or delayed purchases) before then, or ' + fmt(r.needed) + ' to stay above your cushion.');
    } else if (r.below > 0) {
      verdict.className = 'callout callout-caution mt-5';
      set('cfVerdictTitle', 'Cash stays positive but gets tight');
      set('cfVerdictText', 'The balance dips below your ' + fmt(cushion) + ' cushion in ' + r.below + (r.below === 1 ? ' month' : ' months') + ', with a low of ' + fmt(r.lowest) + ' in ' + lowName + '.');
    } else {
      verdict.className = 'callout callout-success mt-5';
      set('cfVerdictTitle', 'Cash stays above your cushion all year');
      set('cfVerdictText', 'The lowest closing balance is ' + fmt(r.lowest) + ' in ' + lowName + '.');
    }

    var tb = clearBody('cfTable');
    r.rows.forEach(function (row, i) {
      var status = row.close < 0 ? 'Overdrawn' : (row.close < cushion ? 'Below cushion' : 'OK');
      addRow(tb, [monthName(first, i), fmt(row.open), fmt(row.cin), fmt(row.cout), signed(row.cin - row.cout), fmt(row.close), status]);
    });
  }

  function fillMonths() {
    var a = parseFloat(document.getElementById('cfFillIn').value), ga = parseFloat(document.getElementById('cfFillInGrowth').value);
    var b = parseFloat(document.getElementById('cfFillOut').value), gb = parseFloat(document.getElementById('cfFillOutGrowth').value);
    if (isNaN(ga)) ga = 0;
    if (isNaN(gb)) gb = 0;
    var error = document.getElementById('cfError');
    if (isNaN(a) || isNaN(b) || a < 0 || b < 0 || a > 1e10 || b > 1e10 || ga < -100 || gb < -100 || ga > 100 || gb > 100) {
      error.hidden = false;
      error.textContent = 'To fill the months, enter typical amounts of $0 or more and monthly changes from -100% to 100%.';
      return;
    }
    for (var i = 0; i < 12; i++) {
      document.getElementById('cfIn' + (i + 1)).value = String(Math.round(a * Math.pow(1 + ga / 100, i)));
      document.getElementById('cfOut' + (i + 1)).value = String(Math.round(b * Math.pow(1 + gb / 100, i)));
    }
    update();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('cfForm');
    form.addEventListener('input', function (e) { if (!e.target || !/^cfFill/.test(e.target.id || '')) update(); });
    form.addEventListener('change', function (e) { if (!e.target || !/^cfFill/.test(e.target.id || '')) update(); });
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    document.getElementById('cfFill').addEventListener('click', fillMonths);
    update();
  });
})();
